import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

//============= STYLE ===============
const themeStyle = `
.chart-scroll {
  overflow-x: auto;
  overflow-y: hidden;
}

.history-header {
  background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
  border-radius: 8px 8px 0 0 !important;
  padding: 20px !important;
}

.history-header .card-title {
  color: white !important;
  margin: 0 !important;
  font-weight: bold;
  font-size: 1.25rem;
}

.card {
  border: none !important;
  box-shadow: 0 0 2rem 0 rgba(136,152,170,.15) !important;
  border-radius: .75rem !important;
}
`;

// ====== รวมข้อมูลทุก 5 วินาที ======
const averageBy5Seconds = (labels, series) => {
  const bucket = {};

  labels.forEach((label, i) => {
    // label = HH:MM:SS
    const [h, m, s] = label.split(":").map(Number);
    const roundedSec = Math.floor(s / 5) * 5;

    const key = `${h.toString().padStart(2,"0")}:${m
      .toString().padStart(2,"0")}:${roundedSec.toString().padStart(2,"0")}`;

    if (!bucket[key]) bucket[key] = { sum: 0, count: 0 };
    bucket[key].sum += series[i];
    bucket[key].count += 1;
  });

  return {
    labels: Object.keys(bucket),
    series: [
      Object.values(bucket).map(b =>
        Math.round(b.sum / b.count)
      )
    ]
  };
};

const CAMERA_MAP = {
  CAM01: "วิศวะ",
  CAM02: "วิทยาศาสตร์",
  CAM03: "ศิลปศาสตร์",
  CAM04: "PKY",
};

function History() {
  const [cameraId, setCameraId] = useState("CAM01");
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });

  const handleSearch = async () => {
    const API_BASE = "http://localhost:3001";
    const res = await fetch(`${API_BASE}/api/history?cameraId=${cameraId}`);
    const result = await res.json();

    if (result?.labels?.length) {
      const grouped = averageBy5Seconds(
        result.labels,
        result.series[0]
      );
      setChartState(grouped);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [cameraId]);

  const barOptions = {
    height: "400px",
    axisX: {
      showGrid: false,
      offset: 80,
      labelInterpolationFnc: (value, index) =>
        index % 5 === 0 ? value : null, // ไม่ให้แน่นเกิน
    },
    axisY: { onlyInteger: true, low: 0 },
    fullWidth: true,
  };

  const drawLabel = data => {
    if (data.type === "bar") {
      const color = data.value.y > 20 ? "#f5365c" : "#2dce89";
      data.element.attr({
        style: `stroke:${color};stroke-width:20px`
      });

      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 10,
        style: "font-size:12px;font-weight:bold;text-anchor:middle",
      }).text(data.value.y);
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>

      <Card>
        <Card.Header className="history-header">
          <Card.Title>กราฟสถิติราย 5 วินาที</Card.Title>
        </Card.Header>

        <Card.Body>
          <Form.Select
            className="mb-3"
            value={cameraId}
            onChange={e => setCameraId(e.target.value)}
          >
            <option value="CAM01">วิศวะ</option>
            <option value="CAM02">วิทยาศาสตร์</option>
            <option value="CAM03">ศิลปศาสตร์</option>
            <option value="CAM04">PKY</option>
          </Form.Select>

          <div className="chart-scroll">
            <div style={{ width: Math.max(chartState.labels.length * 40, 800) }}>
              <ChartistGraph
                data={chartState}
                type="Bar"
                options={barOptions}
                listener={{ draw: drawLabel }}
              />
            </div>
          </div>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default History;
